#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long minimalKSum(vector<int>& nums,int k){sort(nums.begin(),nums.end());long long cur=1,ans=0;
  for(int x:nums){if(x<cur)continue;long long cnt=min((long long)k,(long long)x-cur);
   ans+=cnt*(2*cur+cnt-1)/2;k-=cnt;cur=(long long)x+1;if(!k)return ans;
  }return ans+(long long)k*(2*cur+k-1)/2;
 }
};
